/**
 * What `pdfredeval publish-cases` sends. The ground truth is kept, never served.
 * @summary Publish a case and its ground truth (staff)
 */
export const publishBenchmarkCase = async (suite: string,
    publishBenchmarkCaseBody: PublishBenchmarkCaseBody, options?: Parameters<typeof customFetch>[1]): Promise<CaseOut> => {
    const formData = new FormData();
if(publishBenchmarkCaseBody.visibility !== undefined) {
 formData.append(`visibility`, publishBenchmarkCaseBody.visibility);
 }
formData.append(`pdf`, publishBenchmarkCaseBody.pdf);
formData.append(`ground_truth`, publishBenchmarkCaseBody.ground_truth);

  return customFetch<CaseOut>(getPublishBenchmarkCaseUrl(suite),
  {
    ...options,
    method: 'POST'
    ,
    body: formData
  }
);}





